package in.smartcampus;
import jakarta.servlet.*;import jakarta.servlet.http.*;import jakarta.servlet.annotation.*;import java.io.*;import java.sql.*;
@WebServlet(urlPatterns={"/login","/register","/logout"})
public class AuthServlet extends HttpServlet {
 protected void doGet(HttpServletRequest q,HttpServletResponse r)throws IOException,ServletException {String p=q.getServletPath(); if(p.equals("/logout")){HttpSession s=q.getSession(false);if(s!=null)s.invalidate();r.sendRedirect(q.getContextPath()+"/?msg=loggedout");return;} q.getRequestDispatcher(p.equals("/register")?"/register.jsp":"/login.jsp").forward(q,r);}
 protected void doPost(HttpServletRequest q,HttpServletResponse r)throws IOException,ServletException {String p=q.getServletPath(); if(p.equals("/register")){register(q,r);return;} login(q,r);}
 private void register(HttpServletRequest q,HttpServletResponse r)throws IOException,ServletException {String name=q.getParameter("name"),email=q.getParameter("email"),pw=q.getParameter("password"); if(name==null||email==null||pw==null||name.isBlank()||!email.contains("@")||pw.length()<8){r.sendRedirect(q.getContextPath()+"/register?error=Check+your+details+and+use+a+password+of+8+characters");return;} try(Connection c=DB.get();PreparedStatement ps=c.prepareStatement("INSERT INTO users(name,email,password_hash,role) VALUES(?,?,?,'STUDENT')")){ps.setString(1,name.trim());ps.setString(2,email.trim().toLowerCase());ps.setString(3,Security.hash(pw));ps.executeUpdate();r.sendRedirect(q.getContextPath()+"/login?msg=Account+created.+Please+sign+in");}catch(SQLIntegrityConstraintViolationException e){r.sendRedirect(q.getContextPath()+"/register?error=That+email+is+already+registered");}catch(Exception e){throw new ServletException(e);}}
 private void login(HttpServletRequest q,HttpServletResponse r)throws IOException,ServletException {String email=q.getParameter("email"),pw=q.getParameter("password"); try(Connection c=DB.get();PreparedStatement ps=c.prepareStatement("SELECT id,name,email,password_hash,role FROM users WHERE email=?")){ps.setString(1,email==null?"":email.trim().toLowerCase());try(ResultSet rs=ps.executeQuery()){if(rs.next()&&Security.verify(pw==null?"":pw,rs.getString("password_hash"))){HttpSession s=q.getSession(true);s.setAttribute("userId",rs.getInt("id"));s.setAttribute("userName",rs.getString("name"));s.setAttribute("userEmail",rs.getString("email"));s.setAttribute("role",rs.getString("role"));r.sendRedirect(q.getContextPath()+"/dashboard");}else r.sendRedirect(q.getContextPath()+"/login?error=Invalid+email+or+password");}}catch(Exception e){throw new ServletException(e);}}
}